fn is_palindrome(text: Vec<char>) -> bool {
    let len = text.len();
    for i in 0..len / 2 {
        let left = text[i].to_ascii_lowercase();
        let right = text[len - 1 - i].to_ascii_lowercase();

        if left != right {
            return false;
        }
    }
    true
}